  "land.cl3.d": "วิดเจ็ตมุมขวาล่างของเว็บตอบคำถามเรื่องการใช้งานผลิตภัณฑ์ทันที และส่งต่อคำถามที่ซับซ้อนเป็นงานให้ทีมมนุษย์ติดตามได้ในคลิกเดียว",
